def shipping_cost(order_total, is_member):
    if is_member:
        return 0
    elif order_total >= 50:
        return 0
    elif order_total >= 20:
        return 4.99
    else:
        return 7.99


total = float(input())
print(f"Shipping: ${shipping_cost(total, False):.2f}")

